import json,sys,base64,re,html
def b(d):
    d=d.replace('-','+').replace('_','/'); d+='='*(-len(d)%4)
    return base64.b64decode(d).decode('utf-8','replace')
def body(p):
    out=[]
    if p.get('body',{}).get('data') and p.get('mimeType','').startswith('text/plain'):
        out.append(b(p['body']['data']))
    for q in p.get('parts',[]) or []:
        out+=body(q)
    if not out and p.get('body',{}).get('data'):
        t=b(p['body']['data']); t=re.sub('<[^>]+>',' ',t); out.append(html.unescape(t))
    return out
def show(t, maxlen=3000):
    msgs=t.get('messages',[t])
    for m in msgs:
        h={x['name']:x['value'] for x in m['payload'].get('headers',[])}
        print('-----',h.get('Date'),'|',h.get('From'),'| To:',h.get('To'),'| Cc:',h.get('Cc'),'|',h.get('Subject'))
        txt='\n'.join(body(m['payload']))
        # strip quoted
        lines=[l for l in txt.splitlines() if not l.startswith('>')]
        print('\n'.join(lines)[:maxlen])
src=sys.argv[1]
ml=int(sys.argv[2]) if len(sys.argv)>2 else 3000
raw=open(src).read() if src!='-' else sys.stdin.read()
j=json.loads(raw)
if 'result' in j: j=json.loads(j['result'])
show(j,ml)
EOF
